146	    /**
147	     * This claim's due: the due fixed when settled; else the greater of the sheet's floor in force on its date and its
148	     * {@link #figure} plus, while it is overdue, its late charge on that figure (a correction has no floor and no
149	     * charge); null when there is no figure.
150	     */
151	    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
152	        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
153	        if (figure == null || settledDue != null || correction()) {
154	            return figure;
155	        }
156	        return figure.add(late.charge(this, grade, figure)).max(floor.on(date));
157	    }
