159	    /**
160	     * This claim's figure: the due fixed when settled, else the rate figure its statement bound (unless PENDING), else
161	     * its amount at the grade's rate in force on its date (the floor is applied last, in {@link #due}); null when
162	     * there is none.
163	     */
164	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
165	        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
166	    }
167	
168	    /** This claim's {@link #figure}, its live figure rounded by the mode. */
169	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
170	        if (settledDue != null) {
171	            return new BigDecimal(settledDue);
172	        }
173	        if (bound()) {
174	            return statedDue == null ? null : new BigDecimal(statedDue);
175	        }
176	        return Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
177	    }
