321	            ps.setBigDecimal(3, input.amount());
322	            ps.setDate(4, Date.valueOf(input.date()));
323	            ps.setString(5, input.note());
324	            ps.setString(6, input.corrects());
325	            ps.setDate(7, Date.valueOf(dueBy));
326	            ps.setString(8, input.ref());
327	            ps.setString(9, kept(input.tags()));
328	            ps.setString(10, kept(input.tags()));
