339	    /**
340	     * Re-fixes the due-by of every claim on the sheet that is not SETTLED or VOID and whose due-by is on or after the
341	     * date: the terms-th business day after its date, with the terms it was fixed with, skipping weekends and the
342	     * holidays given.
343	     */
344	    public void refixDueBy(String sheet, LocalDate from, Set<LocalDate> holidays) {
345	        List<Fixed> fixed = jdbc.query("SELECT id, claimed_on, due_terms FROM claim WHERE sheet = ?"
346	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ?",
347	                (rs, i) -> new Fixed(rs.getLong("id"), rs.getDate("claimed_on").toLocalDate(), rs.getInt("due_terms")),
348	                sheet, Date.valueOf(from));
349	        for (Fixed claim : fixed) {
350	            LocalDate dueBy = Holidays.businessDaysAfter(claim.date(), claim.terms(), holidays);
351	            jdbc.update("UPDATE claim SET due_by = ? WHERE sheet = ? AND id = ?", Date.valueOf(dueBy), sheet, claim.id());
352	        }
353	    }
