473	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
474	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
475	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
476	                id, from.name()) == 1;
477	    }
478	
479	    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
480	    public boolean defer(String sheet, long id, LocalDate until) {
481	        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
482	                Date.valueOf(until), sheet, id) == 1;
483	    }
484	
485	    /**
486	     * Reminds an OPEN or PENDING claim on the date (the sheet's today), conditional on its status read and on it not
487	     * yet being reminded that day: false when it was not.
488	     */
489	    public boolean remind(String sheet, long id, ClaimStatus status, LocalDate today) {
490	        return jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet = ? AND id = ? AND status = ?"
491	                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), sheet, id, status.name(),
492	                Date.valueOf(today)) == 1;
493	    }
494	
495	    /**
496	     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
497	     * another user is refused, not overwritten: false when it was not.
498	     */
499	    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
500	        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
501	                sheet, id, status.name(), was) == 1;
502	    }
503	
504	    /** Fixes the claim's due as it is settled, or leaves none with null. */
505	    public void setSettledDue(String sheet, long id, BigDecimal due) {
506	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
507	    }
508	
509	    /**
510	     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
511	     * user is refused, not overwritten; false when it was not.
512	     */
513	    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
514	        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
515	                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
516	    }
517	
518	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
519	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
520	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
521	    }
522	
523	    /** Unbinds every claim of the person bound by their last statement, so each is live again. */
524	    public void unbindPerson(String sheet, long person) {
525	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet = ? AND person = ? AND stated",
526	                sheet, person);
527	    }
528	
529	    /** Records the user who opened the claim. */
530	    public void setOpenedBy(String sheet, long id, String user) {
531	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
532	    }
533	
534	    /** Sets the claim's number on the sheet, or clears it with null. */
535	    public void setNumber(String sheet, long id, Integer number) {
536	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
537	    }
538	
539	    /** Sets the claim's number within its period. */
540	    public void setPeriodNumber(String sheet, long id, String periodNumber) {
541	        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
542	    }
543	
544	    /**
545	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
546	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
547	     */
548	    public int nextPeriodNumber(String sheet, String period) {
549	        while (true) {
550	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
551	                    sheet, period) == 1) {
552	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
553	                        Integer.class, sheet, period);
554	            }
555	            try {
556	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
557	                return 1;
558	            } catch (DuplicateKeyException raced) {
559	                // Another user took the period's first number at the same moment: take the one after it.
560	            }
561	        }
562	    }
563	
564	    /**
565	     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
566	     * transaction ends, so two claims opened at once get different numbers.
567	     */
568	    public int nextNumber(String sheet) {
569	        while (true) {
570	            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
571	                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
572	                        sheet);
573	            }
574	            try {
575	                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
576	                return 1;
577	            } catch (DuplicateKeyException raced) {
578	                // Another user took the sheet's first number at the same moment: take the one after it.
579	            }
580	        }
581	    }
582	}
583	package net.officefloor.hq.app.claim;
584	
585	import java.math.BigDecimal;
586	import java.math.RoundingMode;
587	import java.time.LocalDate;
588	import java.time.temporal.ChronoUnit;
589	import java.util.List;
590	import java.util.Map;
591	import net.officefloor.hq.app.setting.Dated;
592	import net.officefloor.hq.app.setting.DatedValue;
593	import net.officefloor.hq.app.setting.Settings;
594	
595	/**
596	 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
597	 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
598	 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
599	 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
600	 * that date is given past its due-by before it is overdue.
601	 */
602	public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace) {
603	
604	    /**
605	     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
606	     * the claim it corrects) before the policy date, half to even on or after it.
607	     */
608	    public RoundingMode rounding(Claim claim) {
609	        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
610	    }
611	
612	    /**
613	     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
614	     * grade (its person's in force on its date; null for none) in force on its date, if any.
615	     */
616	    public LocalDate graceBy(Claim claim, String grade) {
617	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
618	        List<DatedValue> history = grade == null ? null : grace.get(grade);
619	        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
620	        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
621	    }
622	
623	    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
624	    public boolean overdue(Claim claim, String grade) {
625	        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
626	    }
627	
628	    /**
629	     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
630	     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
631	     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
632	     * nothing); 0.00 when it is not overdue, and always for a correction.
633	     */
634	    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
635	        BigDecimal total = BigDecimal.ZERO.setScale(2);
636	        if (figure == null || claim.correction() || !overdue(claim, grade)) {
637	            return total;
638	        }
639	        LocalDate dueBy = graceBy(claim, grade);
640	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
641	        for (long k = 1; k <= periods; k++) {
642	            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
643	            if (boundaryPct.signum() != 0) {
644	                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
645	            }
646	        }
647	        return total;
648	    }
649	}
