1	import { useQuery } from '@tanstack/react-query';
2	import { getJson } from '../../api/http';
3	import { gradeOn, setAsideOn, usePeople } from '../people/people';
4	import type { Person } from '../people/people';
5	import { dueCents, hundredths, rateOf, twoDecimals, useRates, type Rate } from '../rates/rates';
6	import { useSheetToday } from '../sheet/sheet';
7	import { useCapCents, useFloorCents, useGraceDays, useLatePctCents, usePolicyDate, type DatedCents } from '../settings/settings';
8	
9	/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN/PENDING -> VOID. A clerk's settle of a
10	 *  due above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). */
11	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
12	
13	/** Every status, in the order the screen lists them. */
14	export const CLAIM_STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];
15	
16	/** How many of the claims have the status (every claim, whoever's). */
17	export function statusCount(claims: Claim[], status: ClaimStatus): number {
18	  return claims.filter((c) => c.status === status).length;
19	}
20	
21	/** A status change a claim's row offers; the server refuses one its status does not allow. */
22	export type ClaimStatusChange = 'open' | 'settle' | 'void' | 'approve' | 'reject';
23	
24	/** Whether a claim is still open: OPEN, or PENDING (handled like OPEN, but not bound by a statement). */
25	export function isOpen(claim: Claim): boolean {
26	  return claim.status === 'OPEN' || claim.status === 'PENDING';
27	}
28	
29	/** Whether a claim's statement binds its figure: it is stated and not PENDING (which shows its live figure). */
30	export function bound(claim: Claim): boolean {
31	  return claim.stated && claim.status !== 'PENDING';
32	}
33	
34	/** A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its number on
35	 * the sheet (given when it is opened; null while a draft; kept once voided), and its due fixed when it was
36	 * settled (two decimals; null while live: until settled, and when its grade had no rate then), and the
37	 * user who opened it (null until opened; that user may not settle it), and whether its person's last statement
38	 * bound it, with the figure it bound (null when its grade had no rate then), and the number the claim it
39	 * corrects shows (null unless it is a correction: a negative amount), and the date it rounds on (its own, or for a
40	 * correction the date of the claim it corrects), and its number within its period (<period>-<n>, or X-<n> in no
41	 * period) when it was opened while the sheet numbered by period, shown in place of its number (null otherwise), and
42	 * its due-by (yyyy-MM-dd), fixed when it was added as the terms-th business day after its date (skipping weekends and holidays), from the terms of its person's grade in force on its date (worked out again with those terms when a holiday on or before it is added, unless SETTLED or VOID), and
43	 * its status log, oldest first, and the date it was last deferred until (null when never), with whether it is
44	 * deferred now (OPEN with that date after the sheet's today: it counts in no total, is not overdue and cannot be
45	 * settled), and the number the claim it was split off shows (null unless it was split off one). */
46	export type Claim = {
47	  id: number;
48	  person: number;
49	  amount: string;
50	  date: string;
51	  note: string;
52	  status: ClaimStatus;
53	  number: number | null;
54	  settledDue: string | null;
55	  openedBy: string | null;
56	  stated: boolean;
57	  statedDue: string | null;
58	  corrects: string | null;
59	  roundsOn: string;
60	  periodNumber: string | null;
61	  dueBy: string;
62	  log: ClaimLogLine[];
63	  deferredUntil: string | null;
64	  deferred: boolean;
65	  /** How many proofs the claim has: one above the sheet's proof threshold needs one to be settled or approved. */
66	  proofs: number;
67	  splitFrom: string | null;
68	  /** The user whose open editor locks the claim against everyone else's edit button (null when none does). */
69	  lockedBy: string | null;
70	  /** Whether it was added while the period its due-by falls in was soft-closed. */
71	  lateEntry: boolean;
72	  /** The sheet's today it was last reminded on (null when never): an OPEN or PENDING claim is reminded once per day. */
73	  remindedOn: string | null;
74	  /** Its external reference, trimmed (null for none): no two claims on the sheet share one, ignoring case. */
75	  ref: string | null;
76	  /** Its tags: each trimmed and lower-cased, repeats dropped, sorted (a claim split off another carries its tags). */
77	  tags: string[];
78	  /** Every tag it has ever carried, sorted: the sheet lists a due-total for each tag any of its claims ever carried. */
79	  tagsEver: string[];
80	  /** The number of the bulk settle batch that last settled it (null when settled one at a time, or never). */
81	  batch: number | null;
82	  /** Its comments, in the order written. */
83	  comments: ClaimComment[];
84	};
85	
86	/** One comment on a claim: the user who wrote it, the sheet's today then (yyyy-MM-dd), and its text. */
87	export type ClaimComment = { by: string; on: string; text: string };
88	
89	/** One line of a claim's status log: the status it took, by whom, on the sheet's today then (yyyy-MM-dd), and the
90	 * claim's due as computed at that moment (two decimals, or n/a). */
91	export type ClaimLogLine = { status: ClaimStatus; by: string; on: string; due: string };
92	
93	export const claimsKey = (sheet: string) => ['claims', sheet] as const;
94	
95	export const claimsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/claims`;
96	
97	/** Every claim on the sheet, newest first. */
98	export function useClaims(sheet: string) {
99	  return useQuery({
100	    queryKey: claimsKey(sheet),
101	    queryFn: () => getJson<Claim[]>(claimsPath(sheet)),
102	  });
103	}
104	
105	/** The claims that count toward claimed, due-total and every total: the OPEN, PENDING and SETTLED ones, but not
106	 *  the deferred ones, nor the OPEN or PENDING ones dated within a hold of their person or whose person's retirement
107	 *  date is reached, unless bound by a statement. */
108	export function counted(claims: Claim[], people: Person[]): Claim[] {
109	  const byId = new Map(people.map((p) => [p.id, p]));
110	  return claims.filter((c) => {
111	    if (c.deferred) return false;
112	    if (c.status === 'SETTLED') return true;
113	    if (!isOpen(c)) return false;
114	    const person = byId.get(c.person);
115	    return bound(c) || person === undefined || !setAsideOn(person, c.date);
116	  });
117	}
118	
119	/** The status a claim had at the end of the day (yyyy-MM-dd), as its status log records it (the last line on or before
120	 *  it); undefined when it was not yet added then. A claim kept from before the log (no lines) has its status now. */
121	export function statusOn(claim: Claim, end: string): ClaimStatus | undefined {
122	  if (claim.log.length === 0) return claim.status;
123	  let then: ClaimStatus | undefined;
124	  for (const line of claim.log) if (line.on <= end) then = line.status;
125	  return then;
126	}
127	
128	/** Whether a claim counts toward a period ending on the day (yyyy-MM-dd): by the status it had at the end of it
129	 *  (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now (as {@link counted}), unbound and
130	 *  dated within a hold of its person or its person's retirement date is reached. */
131	export function countedOn(claim: Claim, person: Person | undefined, end: string): boolean {
132	  const then = statusOn(claim, end);
133	  if (claim.deferred || then === undefined) return false;
134	  if (then === 'SETTLED') return true;
135	  if (then !== 'OPEN' && then !== 'PENDING') return false;
136	  return !isOpen(claim) || bound(claim) || person === undefined || !setAsideOn(person, claim.date);
137	}
138	
139	/** The sum of the claims' amounts with two decimals, added in whole cents so no float error shows. */
140	export function claimed(claims: Claim[]): string {
141	  return twoDecimals(claims.reduce((sum, c) => sum + hundredths(c.amount), 0n));
142	}
143	
144	/** Whether a claim is a correction: a negative amount, correcting the settled claim it names by number. */
145	export function correction(claim: Claim): boolean {
146	  return claim.amount.startsWith('-');
147	}
148	
149	/** Whether a claim keeps its figure whatever the rates: fixed when settled, or bound by a statement (a claim
150	 *  settled or bound when its grade had no rate keeps none). */
151	export function fixed(claim: Claim): boolean {
152	  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
153	}
154	
155	/** What makes an overdue claim's late charge: the sheet's late percent (in hundredths) by date, the one in force on
156	 *  each 30-day boundary after the claim's due-by, and its today.
157	 *  The charge is never bound by a statement: it follows the sheet's today. It also carries the sheet's policy date
158	 *  (yyyy-MM-dd; undefined: its today), which decides how a claim's live figures round. And the date a claim's
159	 *  overdue days are counted from (yyyy-MM-dd): its due-by plus the grace of its person's grade in force on its date,
160	 *  where that grade has one in force on that date. */
161	export type Late = { pct: DatedCents; today: string | undefined; policy: string | undefined; graceBy: (claim: Claim) => string };
162	
163	/** The sheet's late percent, today, policy date and graces. */
164	export function useLate(sheet: string): Late {
165	  const today = useSheetToday(sheet);
166	  const policy = usePolicyDate(sheet);
167	  const grace = useGraceDays(sheet);
168	  const { data: people } = usePeople(sheet);
169	  const graceBy = (claim: Claim) => {
170	    const person = people?.find((p) => p.id === claim.person);
171	    const days = person === undefined ? 0 : grace(gradeOn(person, claim.date), claim.date);
172	    return days === 0 ? claim.dueBy : plusDays(claim.dueBy, days);
173	  };
174	  return { pct: useLatePctCents(sheet), today, policy: policy === '' ? today : policy, graceBy };
175	}
176	
177	/** Whether a claim's live figures round half up: it rounds on a date (its own, or for a correction the date of the
178	 *  claim it corrects) before the policy date; on or after it they round half to even. */
179	export function roundsHalfUp(claim: Claim, late: Late): boolean {
180	  return late.policy !== undefined && claim.roundsOn < late.policy;
181	}
182	
183	/** A claim's figure: the one fixed when it was settled, else the rate figure its statement bound, else its amount at the
184	 *  grade's rate in force on its date (in hundredths); the floor is applied last, in {@link claimDueCents}. */
185	export function claimFigureCents(claim: Claim, pct: string | undefined, floor: DatedCents, halfUp = false): bigint | undefined {
186	  if (claim.settledDue !== null) return hundredths(claim.settledDue);
187	  if (bound(claim)) return claim.statedDue === null ? undefined : hundredths(claim.statedDue);
188	  return dueCents(claim.amount, pct, halfUp);
189	}
190	
191	/** The whole days a claim is overdue: from its due-by plus its grace to the sheet's today (0 when it is not overdue). */
192	function daysOverdue(claim: Claim, late: Late): number {
193	  if (!overdue(claim, late)) return 0;
194	  return Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${late.graceBy(claim)}T00:00:00Z`)) / 86_400_000);
195	}
196	
197	/** The day (yyyy-MM-dd) the given number of days after a day. */
198	function plusDays(day: string, days: number): string {
199	  return new Date(Date.parse(`${day}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
200	}
201	
202	/** A claim's late charge on its figure (in hundredths), compounding: for each full 30 days it is overdue, the late
203	 *  percent in force on that boundary (its due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the
204	 *  charges of the boundaries before it, rounded as the claim's live figures
205	 *  are (see {@link roundsHalfUp}), the charges added up; a correction has none. */
206	export function lateCents(claim: Claim, figure: bigint, late: Late): bigint {
207	  if (correction(claim)) return 0n;
208	  const periods = Math.floor(daysOverdue(claim, late) / 30);
209	  let total = 0n;
210	  for (let k = 1; k <= periods; k++) {
211	    const pct = late.pct(plusDays(late.graceBy(claim), 30 * k));
212	    if (pct === 0n) continue;
213	    const product = (figure + total) * pct;
214	    const quotient = product / 10000n;
215	    const remainder = product % 10000n;
216	    const up = remainder > 5000n || (remainder === 5000n && (roundsHalfUp(claim, late) || quotient % 2n === 1n));
217	    total += up ? quotient + 1n : quotient;
218	  }
219	  return total;
220	}
221	
222	/** A claim's due: the one fixed when settled; else the greater of the sheet's floor in force on its date and its
223	 *  figure plus, while it is overdue, its late charge on that figure (a correction has no floor and no charge). */
224	export function claimDueCents(claim: Claim, pct: string | undefined, floor: DatedCents, late: Late): bigint | undefined {
225	  const figure = claimFigureCents(claim, pct, floor, roundsHalfUp(claim, late));
226	  if (figure === undefined || claim.settledDue !== null || correction(claim)) return figure;
227	  const charged = figure + lateCents(claim, figure, late);
228	  const least = floor(claim.date);
229	  return charged >= least ? charged : least;
230	}
231	
232	
233	/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
234	 *  has no rate on the sheet's today, unless a claim has a figure apart from it (settled, stated, at another grade
235	 *  in force on its date, or from a rate that ended by today on a claim not dated after it): then the figures there are.
236	 *  With a cap, a due-total above it is the cap (an n/a one is not capped). */
237	export function personDueCents(
238	  claims: Claim[],
239	  rates: Rate[],
240	  person: Person,
241	  today: string | undefined,
242	  floor: DatedCents,
243	  late: Late,
244	  cap?: bigint,
245	): bigint | undefined {
246	  const sum = uncappedPersonDueCents(claims, rates, person, today, floor, late);
247	  return sum !== undefined && cap !== undefined && sum > cap ? cap : sum;
248	}
249	
250	/** A person's due-total before the cap: the sum of their figures (see {@link personDueCents}). */
251	export function uncappedPersonDueCents(
252	  claims: Claim[],
253	  rates: Rate[],
254	  person: Person,
255	  today: string | undefined,
256	  floor: DatedCents,
257	  late: Late,
258	): bigint | undefined {
259	  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
260	  // A claim has a figure apart from today's grade when it keeps one, or when another grade in force on its date gives one.
261	  const apart = (c: Claim) => {
262	    const then = gradeOn(person, c.date);
263	    return fixed(c) || (then !== undefined && then !== person.grade && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined)
264	      || (then !== undefined && today !== undefined && c.date <= today && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined);
265	  };
266	  if (rateOf(rates, person.grade, today) === undefined && !mine.some(apart)) return undefined;
267	  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n), 0n);
268	}
269	
270	/** A person's settled-total and open-total (in hundredths): the dues of their SETTLED claims that count (at their
271	 *  frozen figures, corrections included) and of their OPEN and PENDING ones that count (see {@link counted}). Together
272	 *  they make the due-total before the cap; a claim with no due adds nothing. */
273	export function splitDueCents(
274	  claims: Claim[],
275	  rates: Rate[],
276	  person: Person,
277	  floor: DatedCents,
278	  late: Late,
279	): { settled: bigint; open: bigint } {
280	  const split = { settled: 0n, open: 0n };
281	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
282	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
283	    if (c.status === 'SETTLED') split.settled += due;
284	    else if (isOpen(c)) split.open += due;
285	  }
286	  return split;
287	}
288	
289	/** A person's recent settled figure: the sum of their SETTLED claims' frozen figures dated within the 90 days up to
290	 *  and including the sheet's today (today and the 89 days before it); a claim settled with no figure adds nothing. */
291	export function recentSettledCents(claims: Claim[], person: Person, today: string | undefined): bigint {
292	  if (today === undefined) return 0n;
293	  const since = plusDays(today, -89);
294	  return claims
295	    .filter((c) => c.person === person.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
296	    .reduce((sum, c) => sum + (c.settledDue === null ? 0n : hundredths(c.settledDue)), 0n);
297	}
298	
299	/** Whether a person is active: they have an OPEN or PENDING claim that counts (see {@link counted}) dated within the
300	 *  30 days up to and including the sheet's today (today and the 29 days before it). */
301	export function isActive(claims: Claim[], person: Person, today: string | undefined): boolean {
302	  if (today === undefined) return false;
303	  const since = plusDays(today, -29);
304	  return counted(claims.filter((c) => c.person === person.id), [person]).some(
305	    (c) => isOpen(c) && c.date >= since && c.date <= today,
306	  );
307	}
308	
309	/** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace before the sheet's today. */
310	export function overdue(claim: Claim, late: Late): boolean {
311	  return isOpen(claim) && !claim.deferred && late.today !== undefined && late.graceBy(claim) < late.today;
312	}
313	
314	/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
315	 *  their dues (in hundredths; a claim with no due adds nothing). */
316	export function overdueCents(
317	  claims: Claim[],
318	  people: Person[],
319	  rates: Rate[],
320	  late: Late,
321	  floor: DatedCents,
322	): { count: number; cents: bigint } {
323	  const byId = new Map(people.map((p) => [p.id, p]));
324	  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late));
325	  const cents = overdueClaims.reduce(
326	    (sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(byId.get(c.person)!, c.date), c.date), floor, late) ?? 0n),
327	    0n,
328	  );
329	  return { count: overdueClaims.length, cents };
330	}
331	
332	/** A person's dues by the age of the claim on the sheet's today (the whole days from its date): their OPEN and
333	 *  PENDING claims that count (see {@link counted}) aged 0 to 30 days, 31 to 60, and 61 or more (in hundredths; a
334	 *  claim dated after today is 0 to 30, and a claim with no due adds nothing). */
335	export function agedCents(
336	  claims: Claim[],
337	  person: Person,
338	  rates: Rate[],
339	  late: Late,
340	  floor: DatedCents,
341	): { upTo30: bigint; upTo60: bigint; over60: bigint } {
342	  const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
343	  const today = late.today;
344	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
345	    if (!isOpen(c)) continue;
346	    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
347	    const days =
348	      today === undefined ? 0 : Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
349	    if (days <= 30) aged.upTo30 += due;
350	    else if (days <= 60) aged.upTo60 += due;
351	    else aged.over60 += due;
352	  }
353	  return aged;
354	}
355	
356	/** Adds up the people's figures, leaving out the single highest and the single lowest when three or more people
357	 *  have a figure. */
358	export function trimmedSum(figures: bigint[]): bigint {
359	  const sum = figures.reduce((s, f) => s + f, 0n);
360	  if (figures.length < 3) return sum;
361	  const max = figures.reduce((m, f) => (f > m ? f : m));
362	  const min = figures.reduce((m, f) => (f < m ? f : m));
363	  return sum - max - min;
364	}
365	
366	/** The sheet's totals: its claimed-total (everyone's counted claims added up), its due-total (everyone's due-total
367	 *  added up, skipping the people whose due-total is n/a, trimmed — see trimmedSum), and how many of the counted claims
368	 *  are overdue, with their total (each person's overdue-total, trimmed), and its settled-total and open-total. */
369	export function useSheetTotals(sheet: string): {
370	  claimed: string;
371	  due: bigint;
372	  overdue: { count: number; cents: bigint };
373	  settled: bigint;
374	  open: bigint;
375	} {
376	  const { data: all = [] } = useClaims(sheet);
377	  const { data: people = [] } = usePeople(sheet);
378	  const { data: rates = [] } = useRates(sheet);
379	  const today = useSheetToday(sheet);
380	  const floor = useFloorCents(sheet);
381	  const late = useLate(sheet);
382	  const cap = useCapCents(sheet);
383	  const due = trimmedSum(
384	    people
385	      .map((p) => personDueCents(all, rates, p, today, floor, late, cap))
386	      .filter((cents): cents is bigint => cents !== undefined),
387	  );
388	  const overdue = overdueCents(all, people, rates, late, floor);
389	  const perPerson = people.map((p) => overdueCents(all, [p], rates, late, floor).cents);
390	  // The settled-total and open-total: everyone's added up, not trimmed.
391	  const split = people.map((p) => splitDueCents(all, rates, p, floor, late));
392	  return {
393	    claimed: claimed(counted(all, people)),
394	    due,
395	    overdue: { count: overdue.count, cents: trimmedSum(perPerson) },
396	    settled: split.reduce((s, x) => s + x.settled, 0n),
397	    open: split.reduce((s, x) => s + x.open, 0n),
398	  };
399	}
400	
401	/** Every tag ever carried by a claim on the sheet, sorted. */
402	export function sheetTags(claims: Claim[]): string[] {
403	  return [...new Set(claims.flatMap((c) => [...c.tagsEver, ...c.tags]))].sort();
404	}
405	
406	/** The due-total of each tag ever used on the sheet (in hundredths): the dues of the claims that count (see
407	 *  {@link counted}) which carry it, a claim with two tags counting in both; a claim with no due adds nothing. */
408	export function useTagDueTotals(sheet: string): { tag: string; cents: bigint }[] {
409	  const { data: all = [] } = useClaims(sheet);
410	  const { data: people = [] } = usePeople(sheet);
411	  const { data: rates = [] } = useRates(sheet);
412	  const floor = useFloorCents(sheet);
413	  const late = useLate(sheet);
